#include <cuda_fp16.h>

__global__ void sum_reduce_kernel(const half* input, half* output, 
                                  int64_t total_elements, int64_t reduce_dim_size, 
                                  int64_t outer_elements, int64_t inner_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate which element we're processing
    int64_t inner_idx = idx % inner_elements;
    int64_t outer_idx = idx / (inner_elements * reduce_dim_size);
    int64_t reduce_idx = (idx / inner_elements) % reduce_dim_size;

    // For each element in the output, we need to sum over the reduce dimension
    int64_t output_idx = outer_idx * inner_elements + inner_idx;

    // Use shared memory for reduction within block
    extern __shared__ half sdata[];

    // Load data into shared memory
    half val = input[idx];
    sdata[threadIdx.x] = val;
    __syncthreads();

    // Perform reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Write result for this block to global memory
    if (threadIdx.x == 0) {
        atomicAdd(&output[output_idx], sdata[0]);
    }
}

