                                         int64_t total_elements, 
                                         int64_t reduce_dim_size,
                                         int64_t outer_elements,
                                         int64_t inner_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= outer_elements * inner_elements) return;

    half sum = 0.0h;
    int64_t base_idx = idx;

    // Sum along the reduce dimension
    for (int64_t i = 0; i < reduce_dim_size; ++i) {
        int64_t input_idx = base_idx + i * inner_elements * outer_elements;
        sum += input[input_idx];
    }

    output[idx] = sum;
}
